<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Outreach Messages</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Recruiter Outreach Messages</h2><div class="table-wrap"><table><tr><th>Seeker</th><th>Job</th><th>Message</th><th>Status</th><th>Sent At</th></tr><?php foreach ($messages as $msg): ?><tr><td><?php echo htmlspecialchars($msg['seeker_name']); ?></td><td><?php echo htmlspecialchars($msg['job_title']); ?></td><td><?php echo nl2br(htmlspecialchars($msg['message'])); ?></td><td><?php echo htmlspecialchars($msg['status']); ?></td><td><?php echo htmlspecialchars($msg['sent_at']); ?></td></tr><?php endforeach; ?></table></div><div class="actions"><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div></div></body></html>
